<style>
    :root { --ink:#17202a; --muted:#718096; --line:#e7edf2; --surface:#fff; --canvas:#f5f8fa; --navy:#172b4d; --teal:#13b8a6; --teal-dark:#0f9488; --shadow:0 12px 32px rgba(23,43,77,.08); }
    *{box-sizing:border-box} body{margin:0;background:var(--canvas);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif} a{color:inherit}.app-shell{min-height:100vh;display:flex}.sidebar{width:245px;flex:0 0 245px;padding:28px 18px;background:var(--navy);color:#fff}.brand{display:flex;align-items:center;gap:11px;padding:0 12px 35px}.brand-mark{width:38px;height:38px;display:grid;place-items:center;border-radius:12px;background:var(--teal);font-size:20px}.brand strong{display:block;font-size:16px;letter-spacing:.02em}.brand small{color:#9fb0c7;font-size:11px}.nav-label{margin:0 12px 10px;color:#7187a4;font-size:10px;font-weight:700;letter-spacing:.14em;text-transform:uppercase}.nav-list{display:grid;gap:6px}.nav-link{display:flex;align-items:center;gap:12px;padding:12px;border-radius:10px;color:#bdc9d9;font-size:14px;text-decoration:none;transition:.2s ease}.nav-link:hover,.nav-link.active{background:rgba(19,184,166,.16);color:#fff}.nav-icon{width:23px;text-align:center;font-size:17px}.sidebar-note{margin:48px 8px 0;padding:16px;border:1px solid rgba(255,255,255,.1);border-radius:13px;background:rgba(255,255,255,.05);color:#aebbd0;font-size:12px;line-height:1.6}.sidebar-note strong{display:block;margin-bottom:4px;color:#fff}.content{min-width:0;flex:1;padding:30px clamp(20px,4vw,58px)}.topbar{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:34px}.eyebrow{margin:0 0 7px;color:var(--teal-dark);font-size:11px;font-weight:800;letter-spacing:.15em;text-transform:uppercase}h1{margin:0;color:var(--navy);font-size:clamp(25px,3vw,34px);letter-spacing:-.04em}.subtitle{margin:8px 0 0;color:var(--muted);font-size:14px}.profile{display:flex;align-items:center;gap:10px;color:var(--muted);font-size:13px}.avatar{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:#d9f8f4;color:var(--teal-dark);font-weight:800}.hero{display:grid;grid-template-columns:1.4fr .8fr;gap:24px;margin-bottom:24px}.hero-card{position:relative;overflow:hidden;padding:clamp(25px,5vw,48px);border-radius:22px;background:linear-gradient(135deg,#16345d,#235b73);color:#fff;box-shadow:var(--shadow)}.hero-card:after{position:absolute;right:-55px;bottom:-90px;width:230px;height:230px;border:35px solid rgba(19,184,166,.18);border-radius:50%;content:''}.hero-card h2{position:relative;z-index:1;max-width:460px;margin:0;font-size:clamp(25px,4vw,42px);line-height:1.08;letter-spacing:-.05em}.hero-card p{position:relative;z-index:1;max-width:480px;margin:16px 0 25px;color:#d7e7ef;line-height:1.7}.button{position:relative;z-index:1;display:inline-flex;align-items:center;gap:8px;padding:11px 16px;border-radius:9px;background:var(--teal);color:#fff;font-size:13px;font-weight:800;text-decoration:none}.button:hover{background:#20c9b6}.button.secondary{background:#eaf1ff;color:#326bd0}.button.secondary:hover{background:#dce8ff}.quick-card{display:flex;flex-direction:column;justify-content:space-between;padding:26px;border:1px solid var(--line);border-radius:22px;background:var(--surface);box-shadow:var(--shadow)}.quick-card .big-number{color:var(--navy);font-size:48px;font-weight:800;letter-spacing:-.06em}.quick-card p{margin:5px 0 20px;color:var(--muted);font-size:13px}.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px}.stat{display:flex;align-items:center;gap:14px;padding:19px;border:1px solid var(--line);border-radius:16px;background:var(--surface);box-shadow:var(--shadow)}.stat-icon{display:grid;place-items:center;width:43px;height:43px;border-radius:12px;background:#e7faf7;color:var(--teal-dark);font-size:19px}.stat:nth-child(2) .stat-icon{background:#fff5dc;color:#c27b00}.stat:nth-child(3) .stat-icon{background:#eaf1ff;color:#326bd0}.stat strong{display:block;color:var(--navy);font-size:22px}.stat span{color:var(--muted);font-size:12px}.panel{padding:25px;border:1px solid var(--line);border-radius:18px;background:var(--surface);box-shadow:var(--shadow)}.panel-heading{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:20px}.panel-heading h2{margin:0;color:var(--navy);font-size:18px}.panel-heading span{color:var(--muted);font-size:12px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:570px}th{padding:13px 15px;border-bottom:1px solid var(--line);color:#8491a4;font-size:10px;letter-spacing:.1em;text-align:left;text-transform:uppercase}td{padding:17px 15px;border-bottom:1px solid #eef2f5;color:#526174;font-size:14px}tr:last-child td{border-bottom:0}tr:hover td{background:#fbfdfd}.person{display:flex;align-items:center;gap:11px;color:var(--navy);font-weight:700}.person-avatar{display:grid;place-items:center;width:33px;height:33px;border-radius:10px;background:#e4f8f5;color:var(--teal-dark);font-size:12px;font-weight:800}.badge{display:inline-block;padding:5px 10px;border-radius:99px;background:#e7faf7;color:var(--teal-dark);font-size:11px;font-weight:800}.badge.manager{background:#fff4d9;color:#aa6d00}.badge.admin{background:#eaf1ff;color:#326bd0}.badge.out{background:#ffe7e8;color:#b4232f}.action-link{display:inline-block;margin-right:10px;color:#326bd0;font-size:12px;font-weight:800;text-decoration:none}.action-link:hover{text-decoration:underline}.action-link.danger{color:#b4232f}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.field{display:grid;gap:7px}.field.full{grid-column:1/-1}.field label{color:var(--navy);font-size:12px;font-weight:800}.input{width:100%;padding:12px 13px;border:1px solid var(--line);border-radius:10px;background:#fbfdfd;color:var(--ink);font:inherit}.input:focus{outline:2px solid rgba(19,184,166,.25);border-color:var(--teal)}.form-actions{display:flex;align-items:center;gap:10px;margin-top:22px}.form-error{padding:12px 14px;margin-bottom:18px;border-radius:10px;background:#ffe7e8;color:#8f1d29;font-size:13px}.current-image{width:100px;height:100px;object-fit:cover;border-radius:12px;border:1px solid var(--line)}@media(max-width:800px){.sidebar{width:78px;flex-basis:78px;padding:20px 10px}.brand{justify-content:center;padding:0 0 28px}.brand>div:not(.brand-mark),.nav-label,.nav-link span:not(.nav-icon),.sidebar-note{display:none}.nav-link{justify-content:center;padding:13px 8px}.hero{grid-template-columns:1fr}}@media(max-width:560px){.content{padding:22px 15px}.topbar{align-items:flex-start}.profile{display:none}.stat-grid,.info-grid,.form-grid{grid-template-columns:1fr}.panel{padding:17px 13px}}
</style>
